import { Meta, StoryObj } from "@storybook/react";
import { expect, within } from "storybook/test";
import { QueueTimeDisplay, queueTimeDisplayVariants } from "./queue-time-display";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";
import { PropsWithChildren } from "react";

// The Label badge grows to fit its parent, and on ride list items the parent is absolutely positioned.
// The frame mimics that so the badge keeps its natural size in the stories.
const Frame = ({ children }: PropsWithChildren) => (
  <div style={{ position: "relative", height: "2.5rem" }}>
    <div style={{ position: "absolute" }}>{children}</div>
  </div>
);

const meta = {
  title: "Primitives/Queue Time Display",
  component: QueueTimeDisplay,
  parameters: {
    docs: {
      description: {
        component:
          'Shows a ride\'s current queue time ("Kötid: 0-10 min") or the stoppage text when the ride is not ' +
          "operating. Renders nothing when the ride is operating but no queue time is available. The text " +
          "renders either in a `Label` badge (as on ride list items) or as a plain span.",
      },
    },
  },
  args: {
    state: 0,
    queueTimeText: "0-10",
    variant: "LABEL",
    className: undefined,
  },
  render: (args) => (
    <Frame>
      <QueueTimeDisplay {...args} />
    </Frame>
  ),
} satisfies Meta<typeof QueueTimeDisplay>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByText("Kötid: 0-10 min")).toBeVisible();
  },
};

export const VariantDisplayStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Display states (state + queueTimeText)" variantType="other">
      <Variant label="operating with queue time">
        <Frame>
          <QueueTimeDisplay {...args} state={0} queueTimeText="0-10" />
        </Frame>
      </Variant>
      <Variant label="stoppage (state other than 0)">
        <Frame>
          <QueueTimeDisplay {...args} state={1} queueTimeText="0-10" />
        </Frame>
      </Variant>
      <Variant label="operating without queue time (renders nothing)">
        <Frame>
          <QueueTimeDisplay {...args} state={0} queueTimeText={undefined} />
        </Frame>
      </Variant>
    </ShowcaseLayout>
  ),
};

export const VariantRendering: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="variant" variantType="prop">
      {queueTimeDisplayVariants.map((variant) => (
        <Variant key={variant} label={variant}>
          <Frame>
            <QueueTimeDisplay {...args} variant={variant} />
          </Frame>
        </Variant>
      ))}
    </ShowcaseLayout>
  ),
};
